create or replace view public.dreem_notification_delivery_summary with (security_invoker=true) as select school_id,announcement_id,channel,status,count(*)::bigint as deliveries,max(updated_at)as last_updated_at from public.dreem_notification_deliveries group by school_id,announcement_id,channel,status;revoke all on public.dreem_notification_delivery_summary from anon;grant select on public.dreem_notification_delivery_summary to authenticated;
create or replace view public.dreem_finance_control_read_model with (security_invoker=true) as select s.id as school_id,coalesce((select sum(balance_due)from public.fee_accounts f where f.school_id=s.id),0)as receivables,coalesce((select sum(amount)from public.dreem_financial_payments p where p.school_id=s.id and p.reverses_payment_id is null),0)as gross_collections,coalesce((select sum(amount)from public.dreem_cash_deposit_batches b where b.school_id=s.id and b.status='confirmed'),0)as confirmed_deposits,coalesce((select count(*)from public.dreem_reconciliation_reviews r where r.school_id=s.id and r.status='pending'),0)as pending_reconciliations,coalesce((select count(*)from public.dreem_refund_requests rr where rr.school_id=s.id and rr.status='pending_review'),0)as pending_refunds,coalesce((select count(*)from public.dreem_cash_deposit_batches b where b.school_id=s.id and b.status in('submitted','pending')),0)as pending_deposits from public.schools s where private.dreem_is_member(s.id);revoke all on public.dreem_finance_control_read_model from anon;grant select on public.dreem_finance_control_read_model to authenticated;